/*
 * quickjs_jit.h - the interpreter's frame state, shared by the interpreter,
 * the per-opcode helpers (quickjs_jsops.inc, generated by
 * tools/gen_jsops.js) and the baseline JIT (quickjs_jit.c and its stencils,
 * quickjs_jit_ops.c).  See JIT_DESIGN.md.
 */
#ifndef QUICKJS_JIT_H
#define QUICKJS_JIT_H

#include <stdint.h>
#include "quickjs_types.h"

/* What a helper (jsop_<op>) or a stretch of JIT code ends with: the
 * interpreter's BREAK, `goto exception`, `goto done` and `goto
 * done_generator`. */
enum {
    JSOP_NEXT = 0,
    JSOP_EXCEPTION = 1,
    JSOP_DONE = 2,
    JSOP_DONE_GENERATOR = 3,
};

struct JitCode;

/* The locals of JS_CallInternal an instruction can use.  sp, pc and
 * ret_val change as instructions run; the rest are fixed for the call.
 * pc points just past the opcode byte of the instruction being run, as in
 * the interpreter's switch. */
typedef struct JSInterpFrame {
    GCValue *sp;
    const uint8_t *pc;
    GCValue ret_val;

    JSContextHandle caller_ctx;
    JSContextHandle ctx;
    JSRuntimeHandle rt;
    JSObjectHandle p;
    JSFunctionBytecodeHandle b;
    struct JSStackFrame *sf;
    GCValue *stack_buf;
    GCValue *var_buf;
    GCValue *arg_buf;
    JSVarRefHandle *var_refs;
    GCHandle var_refs_handle;
    GCHandle *sf_var_refs;
    GCValue func_obj;
    GCValue this_obj;
    GCValue new_target;
    int argc;
    GCValue *argv;
    int flags;

    /* Its frame's pool depth (js_alloc_bytecode_frame), for releasing it. */
    int pool_depth;
    /* JIT code of the function, while it runs compiled. */
    const struct JitCode *code;
    /* What compiled code exits with (JSOP_*), set before its exit stub. */
    int jit_exit;
    /* The bytecode, for offsets: pc - byte_code is the bytecode offset. */
    const uint8_t *byte_code;
} JSInterpFrame;

/* The baseline JIT (quickjs_jit.c). */

/* A compiled function. */
typedef struct JitCode {
    uint8_t *base;              /* its code */
    uint32_t size;
    uint32_t byte_code_len;
    const uint8_t *byte_code;   /* what it was compiled from */
    uint32_t *pc_map;           /* bytecode offset -> code offset; UINT32_MAX: none */
    GCHandle owner;             /* its JSFunctionBytecode */
} JitCode;

/* JSFunctionBytecode.jit_code of a function that cannot be compiled. */
#define JIT_CODE_FAILED ((JitCode *)(uintptr_t)1)

/* Runs compiled code from target (ms_abi). */
extern int (*g_jit_trampoline)(JSInterpFrame *F, void *target);

/* Run compiled code from F->pc (an instruction's address); returns how it
 * stopped (JSOP_*), JSOP_NEXT meaning: continue in the interpreter at
 * F->pc. */
static inline int jit_enter(const JitCode *jc, JSInterpFrame *F)
{
    uintptr_t off = (uintptr_t)(F->pc - jc->byte_code);
    uint32_t at = 0;    /* the function's start is the code's */
    if (off && (off >= jc->byte_code_len || (at = jc->pc_map[off]) == UINT32_MAX))
        return JSOP_NEXT;
    F->code = jc;
    return g_jit_trampoline(F, jc->base + at);
}

/* Fast paths compiled code calls (quickjs.c): 1 when done, 0 (changing
 * nothing) when the instruction must run through its helper. */
const GCValue *jit_field_ref(GCHandle h, JSAtom atom);
const GCValue *jit_prim_field_ref(JSContextHandle ctx, const GCValue *v, JSAtom atom);
int32_t jit_string_length(GCHandle h);
extern const uint32_t jit_atom_length;
int jit_truth(const GCValue *v);
int jit_get_var_ref(const JSVarRefHandle *var_refs, uint32_t idx, GCValue *out);
void jit_put_var_ref(const JSVarRefHandle *var_refs, uint32_t idx, const GCValue *v);
int jit_strict_eq(const GCValue *a);
int jit_loose_eq(const GCValue *a);
int jit_put_field_fast(JSInterpFrame *F, const GCValue *a, JSAtom atom);
const GCValue *jit_array_el_ref(const GCValue *a);
int jit_atom_value(JSContextHandle ctx, JSAtom atom, GCValue *pval);
/* Direct calls from compiled code: call, call_method, call_constructor. */
enum { JIT_CALL_PLAIN, JIT_CALL_METHOD, JIT_CALL_CONSTRUCTOR };
void *jit_call_prepare(JSInterpFrame *F, JSInterpFrame *F2, int argc, int kind);
int jit_call_finish(JSInterpFrame *F, JSInterpFrame *F2, int r, int argc, int kind);
/* helpers: by opcode (jsop_table); jumps: the opcodes whose helper may
 * jump (jsop_jumps); name: for profiles (may be NULL). */
JitCode *jit_compile(JSContextHandle ctx, GCHandle owner, const uint8_t *bc, uint32_t len,
                     const GCValue *cpool, int (*const *helpers)(JSInterpFrame *F), const uint8_t *jumps,
                     const char *name);
void jit_region_bounds(uintptr_t *base, size_t *size);
void jit_print_stats(void);
int jit_available(void);

#endif /* QUICKJS_JIT_H */
